const body = $('Upload Webhook').item.json.body || $('Upload Webhook').item.json;
const driveFile = $('Upload to Drive To-Post').item.json;

// Generate unique Content ID (W-timestamp)
const now = new Date();
const contentId = 'W-' + String(now.getFullYear()).slice(-2) + String(now.getMonth()+1).padStart(2, '0') + String(now.getDate()).padStart(2, '0') + '-' + String(now.getHours()).padStart(2, '0') + String(now.getMinutes()).padStart(2, '0') + String(now.getSeconds()).padStart(2, '0');

const title = body.title || 'Legal Awareness Post';
const caption = body.caption || '';
const platforms = Array.isArray(body.platforms) ? body.platforms.join(',') : (body.platforms || 'instagram,facebook,youtube');

// Scheduled DateTime in ISO 8601 UTC
let scheduledDateTime = body.scheduledDateTime;
if (!scheduledDateTime || scheduledDateTime === 'now') {
  scheduledDateTime = now.toISOString();
} else {
  try {
    scheduledDateTime = new Date(scheduledDateTime).toISOString();
  } catch (e) {
    scheduledDateTime = now.toISOString();
  }
}

const initialStatus = body.status || 'Pending Review'; // 'Pending Review' or 'Approved'
const pinterestBoardId = body.pinterestBoardId || '';

return [{
  json: {
    'Content ID': contentId,
    'Title': title,
    'Caption': caption,
    'Platforms': platforms.toLowerCase(),
    'Scheduled DateTime': scheduledDateTime,
    'Status': initialStatus,
    'Retry Count': 0,
    'Posted At': '',
    'Error': '',
    'Pinterest Board ID': pinterestBoardId,
    'Drive File ID': driveFile.id,
    'Instagram Status': '',
    'Facebook Status': '',
    'YouTube Status': '',
    'LinkedIn Status': '',
    'Pinterest Status': '',
    'Threads Status': '',
    contentId,
    driveFileId: driveFile.id,
    driveFileUrl: driveFile.webViewLink || ('https://drive.google.com/file/d/' + driveFile.id + '/view')
  }
}];

const items = $input.all().map(i => i.json);
// Reverse so newest posts appear first
const rows = items.filter(r => r['Content ID'] && r['Content ID'].trim() !== '');
return [{
  json: {
    success: true,
    count: rows.length,
    posts: rows.reverse()
  }
}];
